    /// <summary>
    /// Update the form controls based on certain logic.
    /// </summary>
    private void updateFormControls()
    {
        if (METPlannerCodeAssignmentRules.RuleAssignmentType == METRuleAssignmentType::Product)
        {
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).allowEdit(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).mandatory(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).allowEdit(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).mandatory(false);            
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorWarehouse)).allowEdit(false);            
        }

        if (METPlannerCodeAssignmentRules.RuleAssignmentType == METRuleAssignmentType::Vendor)
        {
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).mandatory(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).allowEdit(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).mandatory(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).allowEdit(false);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).mandatory(true);            
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorWarehouse)).allowEdit(true);
        }

        if (METPlannerCodeAssignmentRules.RuleAssignmentType == METRuleAssignmentType::VendorProduct)
        {
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategory)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleProductCategoryHierarchy)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorAccount)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).allowEdit(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorSite)).mandatory(true);
            METPlannerCodeAssignmentRules_ds.object(fieldNum(METPlannerCodeAssignmentRules, RuleVendorWarehouse)).allowEdit(true);
        }
    }

        /// <summary>
        /// The active method of the form datasource.
        /// </summary>
        /// <returns>current record</returns>
        public int active()
        {
            int ret;
        
            ret = super();

            element.updateFormControls();
        
            return ret;
        }

            /// <summary>
            /// The modified method of the form datasource field.
            /// </summary>
            public void modified()
            {
                super();

                element.updateFormControls();
                if (METPlannerCodeAssignmentRules.RuleAssignmentType == METRuleAssignmentType::Product)
                {
                    METPlannerCodeAssignmentRules.RuleVendorAccount = METConstants::emptyString;
                    METPlannerCodeAssignmentRules.RuleVendorSite = METConstants::emptyString;
                }
                else if (METPlannerCodeAssignmentRules.RuleAssignmentType == METRuleAssignmentType::Vendor)
                {
                    METPlannerCodeAssignmentRules.RuleProductCategory = 0;
                    METPlannerCodeAssignmentRules.RuleProductCategoryHierarchy = 0;
                }
            }

            /// <summary>
            /// MPJ_19364_PlannerCode by Sathish on 13042022
            /// </summary>
            /// <param name = "_formReferenceControl"> Get Form reference control</param>
            /// <returns>ret</returns>
            public Common resolveReference(FormReferenceControl _formReferenceControl)
            {
                Common ret;
                EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
                EcoResCategoryHierarchy     categoryHierarchy  = EcoResCategoryHierarchy::find(METPlannerCodeAssignmentRules.RuleProductCategoryHierarchy);

                select firstonly ecoResCategoryHierarchyRole
                    where ecoResCategoryHierarchyRole.CategoryHierarchy == categoryHierarchy.RecId;
                
                ret = EcoResCategory::lookupCategoryHierarchy(_formReferenceControl,categoryHierarchy);
                
            
                return ret;
            }

            /// <summary>
            /// MPJ_19364_PlannerCode by Sathish on 13042022
            /// </summary>
            /// <param name = "_formReferenceControl"> Get form reference control</param>
            /// <returns>ret</returns>
            public Common lookupReference(FormReferenceControl _formReferenceControl)
            {
                Common ret;
                EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
                EcoResCategoryHierarchy     categoryHierarchy  = EcoResCategoryHierarchy::find(METPlannerCodeAssignmentRules.RuleProductCategoryHierarchy);

                select firstonly ecoResCategoryHierarchyRole
                    where ecoResCategoryHierarchyRole.CategoryHierarchy == categoryHierarchy.RecId;
                
                ret = EcoResCategory::lookupCategoryHierarchy(_formReferenceControl,categoryHierarchy);
            
                return ret;
            }

            /// <summary>
            /// The lookup method of the datasource field
            /// </summary>
            /// <param name = "_formControl">The form control object.</param>
            /// <param name = "_filterStr">The filter string value</param>
            public void lookup(FormControl _formControl, str _filterStr)
            {                
                Query                   query = new Query();
                QueryBuildDataSource    queryBuildDataSource;
                SysTableLookup          sysTableLookup;

                sysTableLookup = SysTableLookup::newParameters(tableNum(METVendSiteSettingsSetup), _formControl);
                queryBuildDataSource = query.addDataSource(tableNum(METVendSiteSettingsSetup));
                queryBuildDataSource.fields().clearFieldList();
                queryBuildDataSource.fields().addField(fieldNum(METVendSiteSettingsSetup, AssignedSite));
                queryBuildDataSource.fields().addField(fieldNum(METVendSiteSettingsSetup, AssignedVendorAccount));
                queryBuildDataSource.addGroupByField(fieldNum(METVendSiteSettingsSetup, AssignedSite));
                queryBuildDataSource.addSortField(fieldnum(METVendSiteSettingsSetup, AssignedSite));
                queryBuildDataSource.orderMode(ordermode::GroupBy);

                queryBuildDataSource.addRange(fieldNum(METVendSiteSettingsSetup, AssignedVendorAccount)).value(METPlannerCodeAssignmentRules.RuleVendorAccount);
                queryBuildDataSource.addRange(fieldNum(METVendSiteSettingsSetup, AssignedSite)).value(SysQuery::valueNot(METConstants::emptyString));

                sysTableLookup.addLookupField(fieldNum(METVendSiteSettingsSetup, AssignedSite));
                sysTableLookup.parmUseLookupValue(NoYes::No);
                sysTableLookup.parmQuery(query);
                sysTableLookup.performFormLookup();
            }

