            /// <summary>
            /// The lookup method of the datasource field
            /// MPJ_19364_PlannerCode
            /// </summary>
            /// <param name = "_formControl">The form control object.</param>
            /// <param name = "_filterStr">The filter string value</param>
            public void lookup(FormControl _formControl, str _filterStr)
            {
                Query                   query = new Query();
                QueryBuildDataSource    queryBuildDataSource;
                SysTableLookup          sysTableLookup;

                if (METPlannerCodeAssignmentRules.RuleVendorSite)
                {
                    sysTableLookup = SysTableLookup::newParameters(tableNum(METVendSiteSettingsSetup), _formControl);
                    queryBuildDataSource = query.addDataSource(tableNum(METVendSiteSettingsSetup));
                    queryBuildDataSource.fields().clearFieldList();
                    queryBuildDataSource.fields().addField(fieldNum(METVendSiteSettingsSetup, AssignedWH));
                    queryBuildDataSource.fields().addField(fieldNum(METVendSiteSettingsSetup, AssignedVendorAccount));
                    queryBuildDataSource.addGroupByField(fieldNum(METVendSiteSettingsSetup, AssignedWH));
                    queryBuildDataSource.addSortField(fieldnum(METVendSiteSettingsSetup, AssignedWH));
                    queryBuildDataSource.orderMode(ordermode::GroupBy);

                    queryBuildDataSource.addRange(fieldNum(METVendSiteSettingsSetup, AssignedVendorAccount)).value(METPlannerCodeAssignmentRules.RuleVendorAccount);
                    queryBuildDataSource.addRange(fieldNum(METVendSiteSettingsSetup, AssignedSite)).value(METPlannerCodeAssignmentRules.RuleVendorSite);
                    queryBuildDataSource.addRange(fieldNum(METVendSiteSettingsSetup, AssignedWH)).value(SysQuery::valueNot(METConstants::emptyString));

                    sysTableLookup.addLookupField(fieldNum(METVendSiteSettingsSetup, AssignedWH));
                    sysTableLookup.parmUseLookupValue(NoYes::No);
                    sysTableLookup.parmQuery(query);
                    sysTableLookup.performFormLookup();
                }
            }
